def run_rows(rows):
    """Translate one pixel shader that runs every row and stores v4 at BASE + 4k; return the stored words."""
    body = [f"s_mov_b32 s0, {BASE:#x}", "s_mov_b32 s1, 0", "s_mov_b32 s2, 0x1000", "s_mov_b32 s3, 0x31016fac"]
    for k, (lines, a, b, c, _) in enumerate(rows):
        body += [f"v_mov_b32 v1, {a:#x}", f"v_mov_b32 v2, {b:#x}", f"v_mov_b32 v3, {c:#x}", "v_mov_b32 v4, 0xdeadbeef",
                 *lines.split("\n"), f"buffer_store_dword v4, off, s[0:3], 0 offset:{4 * k}"]
    body += ["exp mrt0 v4, v4, v4, v4 done vm", "s_endpgm"]
    with tempfile.TemporaryDirectory() as tmp:
        os.mkdir(os.path.join(tmp, "disasm"))
        src = os.path.join(tmp, "disasm", "ps_vop3_mods_hw.s")
        with open(os.path.join(tmp, "ps_vop3_mods_hw.dxbc"), "wb") as f:
            f.write(STUB_DXBC)
        with open(src, "w", encoding="utf-8") as f:
            f.write("; test_alu_vop3_mods_hw\n" + "".join(f"\t{x}\n" for x in body))
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", ResourceWarning)
            spv = rdna2spirv.translate(src)
    memory = {}
    si.run_fragment(spv, memory=memory)
    return [memory.get(BASE + 4 * k) for k in range(len(rows))]


def op_line(lines):
    return next(x for x in lines.split("\n") if not x.startswith(("s_mov_b32", "v_mov_b32 v4, v3")))


class MeasuredWords(unittest.TestCase):
    def test_rows(self):
        groups = {}
        for row in MEASURED:
            groups.setdefault(op_line(row[0]).split()[0], []).append(row)
        for op, rows in groups.items():
            for lo in range(0, len(rows), CHUNK):
                chunk = rows[lo:lo + CHUNK]
                for row, word in zip(chunk, run_rows(chunk)):
                    with self.subTest(lines=row[0].replace("\n", " ; "), v1=hex(row[1]), v2=hex(row[2])):
                        self.assertEqual(word, row[4])

    def test_every_form_has_rows(self):
        forms = {op_line(row[0]) for row in MEASURED}
        self.assertGreaterEqual(len(forms), 450)


if __name__ == "__main__":
    unittest.main()
